/* V258 - Osteopati bağımsız premium sekme sistemi */
/* V254 - Alt sayfalarda gereksiz dikey boşluklar temizlendi */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: Arial, Helvetica, sans-serif;
    background: #ffffff;
    color: #163047;
}


/* HEADER */

header {
    position: fixed;
    top: 0;
    left: 0;

    width: 100%;
    height: 82px;

    padding: 0 7%;

    display: flex;
    align-items: center;
    justify-content: space-between;

    background: rgba(255, 255, 255, 0.92);
    border-bottom: 1px solid rgba(230, 238, 244, 0.8);
    backdrop-filter: blur(15px);

    z-index: 1000;
    transition: 0.3s;
}

header.scrolled {
    height: 74px;
    box-shadow: 0 8px 30px rgba(32, 63, 82, 0.08);
}

.logo {
    text-decoration: none;
    color: #163047;
    font-size: 23px;
    font-weight: 700;
}

.logo span {
    color: #1783c2;
}


/* NAV */

nav {
    display: flex;
    gap: 32px;
}

nav a {
    position: relative;
    color: #536677;
    text-decoration: none;
    font-size: 15px;
    font-weight: 500;
    transition: 0.2s;
}

nav a:hover {
    color: #1783c2;
}

nav a::after {
    content: "";
    position: absolute;
    left: 0;
    bottom: -8px;
    width: 0;
    height: 2px;
    background: #1783c2;
    transition: 0.25s;
}

nav a:hover::after {
    width: 100%;
}

.header-button {
    padding: 12px 21px;
    background: #1783c2;
    color: white;
    text-decoration: none;
    font-size: 14px;
    border-radius: 9px;
    transition: 0.25s;
}

.header-button:hover {
    background: #116da4;
    transform: translateY(-2px);
}


/* HAMBURGER MENÜ */

.menu-button {
    width: 42px;
    height: 42px;

    display: none;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 5px;

    background: #eef8fd;
    border: none;
    border-radius: 10px;

    cursor: pointer;
}

.menu-button span {
    width: 21px;
    height: 2px;

    background: #174a69;
    border-radius: 10px;

    transition: 0.3s;
}

.menu-button.open span:nth-child(1) {
    transform: translateY(7px) rotate(45deg);
}

.menu-button.open span:nth-child(2) {
    opacity: 0;
}

.menu-button.open span:nth-child(3) {
    transform: translateY(-7px) rotate(-45deg);
}


/* HERO */

.hero {
    min-height: 100vh;

    display: flex;
    align-items: center;

    padding: 130px 7% 70px;

    overflow: hidden;

    background:
        radial-gradient(
            circle at 85% 40%,
            #dff3ff,
            transparent 30%
        ),
        linear-gradient(
            135deg,
            #ffffff,
            #f3faff
        );
}

.hero-container {
    width: 100%;
    max-width: 1350px;

    margin: auto;

    display: grid;
    grid-template-columns: 1.1fr 0.9fr;

    align-items: center;
    gap: 80px;
}

.hero-text {
    max-width: 680px;
}

.hero-tag {
    display: inline-block;

    padding: 9px 15px;
    margin-bottom: 25px;

    background: #eaf7ff;
    color: #1783c2;

    border-radius: 30px;

    font-size: 12px;
    font-weight: 700;
    letter-spacing: 2px;
}

.hero h1 {
    margin-bottom: 25px;

    color: #12344e;

    font-size: 62px;
    line-height: 1.08;
    letter-spacing: -2px;
}

.hero h1 span {
    display: block;
    color: #1783c2;
}

.hero-description {
    max-width: 590px;

    margin-bottom: 32px;

    color: #687b8b;

    font-size: 18px;
    line-height: 1.75;
}


/* HERO BUTONLARI */

.hero-buttons {
    display: flex;
    gap: 14px;
    margin-bottom: 45px;
}

.primary-button,
.outline-button {
    display: inline-block;

    padding: 15px 27px;

    border-radius: 10px;

    text-decoration: none;
    font-size: 15px;
    font-weight: 600;

    transition: 0.25s;
}

.primary-button {
    background: #1783c2;
    color: white;
    box-shadow: 0 10px 25px rgba(23, 131, 194, 0.20);
}

.primary-button:hover {
    background: #116da4;
    transform: translateY(-3px);
}

.outline-button {
    background: white;
    color: #1783c2;
    border: 1px solid #cfe4f1;
}

.outline-button:hover {
    border-color: #1783c2;
    transform: translateY(-3px);
}


/* FEATURES */

.features {
    display: flex;
    flex-wrap: wrap;
    gap: 25px;
}

.feature {
    display: flex;
    align-items: center;
    gap: 10px;
}

.feature-icon {
    width: 30px;
    height: 30px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #dff3ff;
    color: #1783c2;

    border-radius: 50%;

    font-size: 14px;
    font-weight: bold;
}

.feature strong {
    display: block;
    color: #24465f;
    font-size: 13px;
}

.feature span {
    display: block;
    margin-top: 3px;
    color: #80909c;
    font-size: 11px;
}


/* DOKTOR FOTOĞRAFI */

.hero-image-area {
    position: relative;

    display: flex;
    align-items: center;
    justify-content: center;
}

.image-decoration {
    position: absolute;

    width: 470px;
    height: 470px;

    background:
        linear-gradient(
            135deg,
            #dff3ff,
            #bfe6fa
        );

    border-radius: 45% 55% 50% 50%;
    transform: rotate(-8deg);
}

.doctor-image {
    position: relative;
    z-index: 2;

    width: 410px;
    height: 500px;

    overflow: hidden;

    border-radius: 30px;

    box-shadow:
        0 30px 70px
        rgba(32, 78, 107, 0.18);
}

.doctor-image img {
    width: 100%;
    height: 100%;

    object-fit: cover;
    object-position: center;

    transition: 0.5s;
}

.doctor-image:hover img {
    transform: scale(1.035);
}

.doctor-card {
    position: absolute;

    bottom: 35px;
    left: 5px;

    z-index: 5;

    display: flex;
    align-items: center;
    gap: 12px;

    padding: 16px 20px;

    background: white;

    border-radius: 15px;

    box-shadow:
        0 15px 40px
        rgba(30, 67, 88, 0.15);
}

.doctor-card-icon {
    width: 42px;
    height: 42px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #1783c2;
    color: white;

    border-radius: 12px;
    font-size: 24px;
}

.doctor-card span {
    display: block;
    margin-bottom: 4px;
    color: #8596a2;
    font-size: 11px;
}

.doctor-card strong {
    color: #284b63;
    font-size: 14px;
}


/* GENEL BÖLÜMLER */

section {
    scroll-margin-top: 82px;
}

.section-heading {
    max-width: 700px;
    margin: 0 auto 60px;
    text-align: center;
}

.section-heading span,
.contact-title > span {
    color: #1783c2;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 3px;
}

.section-heading h2,
.contact-title h2 {
    margin-top: 12px;
    margin-bottom: 17px;
    color: #12344e;
    font-size: 42px;
}

.section-heading p,
.contact-title p {
    color: #738491;
    font-size: 16px;
    line-height: 1.7;
}


/* HAKKIMDA */

.about {
    padding: 110px 7%;
    background: white;
}

.about-container {
    max-width: 1150px;
    margin: auto;

    display: grid;
    grid-template-columns: 0.9fr 1.1fr;

    gap: 80px;
    align-items: center;
}

.about-photo {
    width: 100%;
    height: 480px;

    overflow: hidden;

    border-radius: 25px;

    box-shadow:
        0 20px 60px
        rgba(23, 70, 98, 0.12);
}

.about-photo img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.about-small {
    color: #1783c2;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 2px;
}

.about-text h3 {
    margin: 15px 0 25px;
    color: #12344e;
    font-size: 38px;
    line-height: 1.2;
}

.about-text p {
    margin-bottom: 18px;
    color: #6d7e8b;
    font-size: 16px;
    line-height: 1.8;
}

.text-button {
    display: inline-block;
    margin-top: 10px;
    color: #1783c2;
    text-decoration: none;
    font-weight: 600;
}


/* HİZMETLER */

.services {
    padding: 110px 7%;
    background: #f5faff;
}

.service-grid {
    max-width: 1150px;
    margin: auto;

    display: grid;
    grid-template-columns: repeat(3, 1fr);

    gap: 24px;
}

.service-card {
    padding: 38px;

    background: white;

    border: 1px solid #e8f0f5;
    border-radius: 20px;

    transition: 0.3s;
}

.service-card:hover {
    transform: translateY(-8px);

    box-shadow:
        0 18px 45px
        rgba(30, 74, 100, 0.10);
}

.service-number {
    width: 48px;
    height: 48px;

    margin-bottom: 25px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #e5f5ff;
    color: #1783c2;

    border-radius: 12px;
    font-weight: bold;
}

.service-card h3 {
    margin-bottom: 14px;
    color: #25475f;
    font-size: 21px;
}

.service-card p {
    color: #778895;
    font-size: 15px;
    line-height: 1.7;
}


/* İLETİŞİM / RANDEVU */

.contact {
    padding: 110px 7%;
    background: white;
}

.appointment-wrapper {
    max-width: 1200px;
    margin: auto;

    padding: 65px;

    display: grid;
    grid-template-columns: 0.85fr 1.15fr;

    gap: 70px;
    align-items: center;

    background:
        linear-gradient(
            135deg,
            #103c5a,
            #176f9e
        );

    border-radius: 30px;

    box-shadow:
        0 25px 70px
        rgba(20, 65, 90, 0.16);
}

.appointment-small {
    display: inline-block;
    margin-bottom: 14px;
    color: #92dcff;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 3px;
}

.appointment-info h2 {
    margin-bottom: 20px;
    color: white;
    font-size: 42px;
    line-height: 1.15;
}

.appointment-info > p {
    margin-bottom: 35px;
    color: #d5e9f4;
    font-size: 16px;
    line-height: 1.7;
}

.contact-details {
    display: grid;
    gap: 13px;
}

.detail-card {
    padding: 16px;

    display: flex;
    align-items: center;

    gap: 14px;

    background:
        rgba(255, 255, 255, 0.09);

    border:
        1px solid
        rgba(255, 255, 255, 0.13);

    border-radius: 14px;
}

.detail-icon {
    min-width: 42px;
    height: 42px;

    display: flex;
    align-items: center;
    justify-content: center;

    background:
        rgba(255, 255, 255, 0.13);

    color: white;

    border-radius: 11px;
    font-size: 18px;
}

.detail-card span {
    display: block;
    margin-bottom: 4px;
    color: #9edaff;
    font-size: 10px;
    letter-spacing: 1px;
}

.detail-card strong {
    color: white;
    font-size: 14px;
}


/* FORM */

.appointment-form-area {
    padding: 35px;

    background: white;

    border-radius: 22px;

    box-shadow:
        0 18px 45px
        rgba(0, 0, 0, 0.12);
}

.form-title {
    margin-bottom: 27px;
}

.form-title h3 {
    margin-bottom: 7px;
    color: #173d57;
    font-size: 27px;
}

.form-title p {
    color: #82909a;
    font-size: 14px;
}

.form-group {
    margin-bottom: 19px;
}

.form-group label {
    display: block;
    margin-bottom: 8px;
    color: #345369;
    font-size: 13px;
    font-weight: 600;
}

.form-group label span {
    color: #9aa7af;
    font-weight: normal;
}

.form-group input,
.form-group textarea,
.form-group select {
    width: 100%;

    padding: 14px 15px;

    background: #f8fbfd;
    color: #233f53;

    border: 1px solid #dfeaf0;
    border-radius: 10px;

    outline: none;

    font-family: inherit;
    font-size: 14px;

    transition: 0.2s;
}

.form-group textarea {
    resize: vertical;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    background: white;
    border-color: #1783c2;

    box-shadow:
        0 0 0 3px
        rgba(23, 131, 194, 0.08);
}

.form-group small {
    display: block;
    margin-top: 7px;
    color: #98a5ae;
    font-size: 11px;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
}

.appointment-button {
    width: 100%;

    padding: 15px 20px;

    background: #1783c2;
    color: white;

    border: none;
    border-radius: 11px;

    cursor: pointer;

    font-size: 15px;
    font-weight: 600;

    transition: 0.25s;
}

.appointment-button:hover {
    background: #116da4;
    transform: translateY(-2px);

    box-shadow:
        0 10px 25px
        rgba(23, 131, 194, 0.20);
}


/* FOOTER */

footer {
    padding: 45px 7%;
    background: #0d2c40;
    color: white;
}

.footer-container {
    max-width: 1200px;
    margin: auto;

    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 30px;
}

footer strong {
    font-size: 18px;
}

footer p {
    margin-top: 7px;
    color: #a8bfce;
    font-size: 12px;
}


/* SAYFA ANİMASYONU */

.reveal {
    opacity: 0;

    transform: translateY(35px);

    transition:
        opacity 0.7s ease,
        transform 0.7s ease;
}

.reveal.active {
    opacity: 1;
    transform: translateY(0);
}


/* SAĞ ALT İLETİŞİM */

.quick-contact {
    position: fixed;

    right: 25px;
    bottom: 25px;

    z-index: 900;

    display: flex;
    align-items: center;

    gap: 9px;

    padding: 13px 18px;

    background: #1783c2;
    color: white;

    text-decoration: none;

    border-radius: 50px;

    box-shadow:
        0 12px 30px
        rgba(23, 131, 194, 0.30);

    transition: 0.25s;
}

.quick-contact span {
    font-size: 18px;
}

.quick-contact strong {
    font-size: 13px;
}

.quick-contact:hover {
    background: #116da4;
    transform: translateY(-4px);
}


/* TABLET */

@media (max-width: 950px) {

    .header-button {
        display: none;
    }

    .menu-button {
        display: flex;
    }

    nav {
        position: absolute;

        top: 82px;
        left: 0;

        width: 100%;

        display: flex;
        flex-direction: column;

        gap: 0;

        padding: 10px 7% 20px;

        background: white;

        border-bottom: 1px solid #e8eef2;

        box-shadow:
            0 20px 30px
            rgba(0, 0, 0, 0.06);

        opacity: 0;
        visibility: hidden;

        transform: translateY(-15px);

        transition: 0.3s;
    }

    nav.open {
        opacity: 1;
        visibility: visible;
        transform: translateY(0);
    }

    nav a {
        padding: 16px 0;
        border-bottom: 1px solid #eef3f6;
    }

    nav a:last-child {
        border-bottom: none;
    }

    nav a::after {
        display: none;
    }

    .hero-container {
        grid-template-columns: 1fr;
        text-align: center;
    }

    .hero-text {
        margin: auto;
    }

    .hero-buttons,
    .features {
        justify-content: center;
    }

    .hero h1 {
        font-size: 48px;
    }

    .hero-image-area {
        margin-top: 30px;
    }

    .about-container {
        grid-template-columns: 1fr;
    }

    .service-grid {
        grid-template-columns: 1fr;
    }

    .appointment-wrapper {
        padding: 45px;
        grid-template-columns: 1fr;
        gap: 45px;
    }
}


/* TELEFON */

@media (max-width: 600px) {

    header {
        height: 70px;
        padding: 0 20px;
    }

    header.scrolled {
        height: 65px;
    }

    .logo {
        font-size: 19px;
    }

    nav {
        top: 70px;
    }

    .hero {
        padding: 110px 20px 60px;
    }

    .hero h1 {
        font-size: 38px;
        letter-spacing: -1px;
    }

    .hero-description {
        font-size: 16px;
    }

    .hero-buttons {
        flex-direction: column;
    }

    .features {
        max-width: 250px;
        margin: auto;

        flex-direction: column;
        align-items: flex-start;
    }

    .doctor-image {
        width: 300px;
        height: 380px;
    }

    .image-decoration {
        width: 330px;
        height: 350px;
    }

    .doctor-card {
        bottom: 20px;
        left: -5px;
    }

    .about,
    .services,
    .contact {
        padding: 80px 20px;
    }

    .section-heading h2,
    .contact-title h2 {
        font-size: 31px;
    }

    .about-photo {
        height: 380px;
    }

    .about-text h3 {
        font-size: 30px;
    }

    .appointment-wrapper {
        padding: 30px 20px;
        border-radius: 22px;
    }

    .appointment-info h2 {
        font-size: 31px;
    }

    .appointment-form-area {
        padding: 25px 18px;
    }

    .form-row {
        grid-template-columns: 1fr;
    }

    .footer-container {
        flex-direction: column;
        text-align: center;
    }

    .quick-contact {
        right: 15px;
        bottom: 15px;

        width: 52px;
        height: 52px;

        justify-content: center;

        padding: 0;
    }

    .quick-contact strong {
        display: none;
    }
}


/* İÇERİKLER */

.content-section {
    padding: 110px 7%;
    background: #f7fbfe;
}

.content-grid {
    max-width: 1150px;
    margin: auto;

    display: grid;
    grid-template-columns: repeat(3, 1fr);

    gap: 24px;
}

.content-card {
    position: relative;

    padding: 36px;

    background: white;

    border: 1px solid #e5eef4;
    border-radius: 22px;

    overflow: hidden;

    transition: 0.3s;
}

.content-card::before {
    content: "";

    position: absolute;

    top: 0;
    left: 0;

    width: 100%;
    height: 4px;

    background:
        linear-gradient(
            90deg,
            #1783c2,
            #76c8f0
        );
}

.content-card:hover {
    transform: translateY(-8px);

    box-shadow:
        0 20px 50px
        rgba(28, 74, 102, 0.10);
}

.content-badge {
    display: inline-block;

    margin-bottom: 22px;

    padding: 7px 10px;

    background: #edf8fe;
    color: #1783c2;

    border-radius: 30px;

    font-size: 10px;
    font-weight: 700;

    letter-spacing: 1.5px;
}

.content-icon {
    width: 54px;
    height: 54px;

    margin-bottom: 22px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #e9f7ff;
    color: #1479b3;

    border-radius: 15px;

    font-size: 23px;
}

.content-card h3 {
    margin-bottom: 14px;

    color: #1c4058;

    font-size: 22px;
}

.content-card p {
    margin-bottom: 24px;

    color: #748691;

    font-size: 15px;
    line-height: 1.75;
}

.content-link {
    color: #1783c2;

    text-decoration: none;

    font-size: 14px;
    font-weight: 700;
}

.content-link:hover {
    text-decoration: underline;
}


.social-callout {
    max-width: 1150px;

    margin: 34px auto 0;

    padding: 38px 42px;

    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 30px;

    background:
        linear-gradient(
            135deg,
            #eaf7ff,
            #f8fcff
        );

    border: 1px solid #d8edf8;
    border-radius: 22px;
}

.social-small {
    display: inline-block;

    margin-bottom: 8px;

    color: #1783c2;

    font-size: 11px;
    font-weight: 700;

    letter-spacing: 2px;
}

.social-callout h3 {
    margin-bottom: 8px;

    color: #183f58;

    font-size: 25px;
}

.social-callout p {
    max-width: 600px;

    color: #748792;

    font-size: 14px;
    line-height: 1.7;
}

.social-buttons {
    display: flex;

    gap: 12px;
}

.social-button {
    display: inline-block;

    padding: 13px 20px;

    background: #1783c2;
    color: white;

    border: 1px solid #1783c2;
    border-radius: 10px;

    text-decoration: none;

    font-size: 13px;
    font-weight: 700;

    transition: 0.25s;
}

.social-button:hover {
    background: #116da4;

    transform: translateY(-2px);
}

.social-button.light {
    background: white;
    color: #1783c2;
}

.social-button.light:hover {
    background: #f2faff;
}


/* İÇERİKLER RESPONSIVE */

@media (max-width: 950px) {

    .content-grid {
        grid-template-columns: 1fr;
    }

    .social-callout {
        flex-direction: column;
