/* V14 RANDEVU ONIZLEME */

body.modal-open {
    overflow: hidden;
}

.appointment-modal {
    position: fixed;
    inset: 0;

    z-index: 4000;

    display: flex;
    align-items: center;
    justify-content: center;

    padding: 20px;

    opacity: 0;
    visibility: hidden;

    transition: 0.25s;
}

.appointment-modal.show {
    opacity: 1;
    visibility: visible;
}

.appointment-modal-backdrop {
    position: absolute;
    inset: 0;

    background: rgba(12, 38, 54, 0.58);

    backdrop-filter: blur(6px);
}

.appointment-modal-card {
    position: relative;

    width: 100%;
    max-width: 540px;

    padding: 34px;

    background: white;

    border-radius: 24px;

    box-shadow:
        0 30px 90px
        rgba(10, 36, 53, 0.28);

    transform: translateY(20px) scale(0.98);

    transition: 0.28s;
}

.appointment-modal.show .appointment-modal-card {
    transform: translateY(0) scale(1);
}

.appointment-modal-close {
    position: absolute;

    top: 16px;
    right: 16px;

    width: 36px;
    height: 36px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #f2f7fa;
    color: #456274;

    border: none;
    border-radius: 50%;

    cursor: pointer;

    font-size: 24px;
    line-height: 1;

    transition: 0.2s;
}

.appointment-modal-close:hover {
    background: #e5f1f7;
    color: #1783c2;
}

.appointment-modal-small {
    display: inline-block;

    margin-bottom: 10px;

    color: #1783c2;

    font-size: 10px;
    font-weight: 800;

    letter-spacing: 2px;
}

.appointment-modal-card h3 {
    margin-bottom: 9px;

    color: #173d57;

    font-size: 27px;
}

.appointment-modal-desc {
    margin-bottom: 24px;

    color: #778995;

    font-size: 13px;
    line-height: 1.65;
}

.appointment-preview {
    display: grid;

    gap: 10px;

    margin-bottom: 25px;
}

.preview-row {
    padding: 12px 14px;

    display: grid;
    grid-template-columns: 150px 1fr;

    gap: 16px;

    background: #f7fbfd;

    border: 1px solid #e5eef3;
    border-radius: 11px;
}

.preview-row span {
    color: #7e909b;

    font-size: 11px;
}

.preview-row strong {
    color: #25485f;

    font-size: 12px;

    word-break: break-word;
}

.appointment-modal-actions {
    display: grid;
    grid-template-columns: 1fr 1fr;

    gap: 10px;
}

.appointment-edit-button,
.appointment-confirm-button {
    padding: 14px 16px;

    border-radius: 10px;

    cursor: pointer;

    font-family: inherit;
    font-size: 13px;
    font-weight: 800;

    transition: 0.22s;
}

.appointment-edit-button {
    background: white;
    color: #476477;

    border: 1px solid #d8e6ed;
}

.appointment-edit-button:hover {
    background: #f7fbfd;
}

.appointment-confirm-button {
    background: #1783c2;
    color: white;

    border: 1px solid #1783c2;
}

.appointment-confirm-button:hover {
    background: #116da4;

    transform: translateY(-2px);
}


