/* V28 HIZMET BILGI MODALI */

.service-card-actions {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
}

.service-info-button {
    padding: 9px 12px;

    background: #eaf7ff;
    color: #1783c2;

    border: 1px solid #d1eaf7;
    border-radius: 9px;

    cursor: pointer;

    font-family: inherit;
    font-size: 12px;
    font-weight: 800;

    transition: 0.22s;
}

.service-info-button:hover {
    transform: translateY(-2px);
    background: #dff3ff;
}

.service-info-modal {
    position: fixed;
    inset: 0;

    z-index: 4300;

    display: flex;
    align-items: center;
    justify-content: center;

    padding: 20px;

    opacity: 0;
    visibility: hidden;

    transition: 0.25s;
}

.service-info-modal.show {
    opacity: 1;
    visibility: visible;
}

.service-info-backdrop {
    position: absolute;
    inset: 0;

    background: rgba(7, 26, 37, 0.72);

    backdrop-filter: blur(7px);
}

.service-info-card {
    position: relative;
    z-index: 1;

    width: 100%;
    max-width: 760px;
    max-height: min(820px, calc(100vh - 40px));

    overflow-y: auto;

    padding: 34px;

    background: white;

    border: 1px solid #e3edf3;
    border-radius: 24px;

    box-shadow:
        0 32px 95px
        rgba(8, 34, 49, 0.30);

    transform: translateY(18px) scale(0.98);

    transition: 0.28s;
}

.service-info-modal.show .service-info-card {
    transform: translateY(0) scale(1);
}

.service-info-close {
    position: absolute;
    top: 16px;
    right: 16px;

    width: 38px;
    height: 38px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #eef5f8;
    color: #476374;

    border: none;
    border-radius: 50%;

    cursor: pointer;

    font-size: 24px;
}

.service-info-kicker {
    display: inline-block;

    margin-bottom: 10px;

    color: #1783c2;

    font-size: 10px;
    font-weight: 800;

    letter-spacing: 2px;
}

.service-info-card h3 {
    padding-right: 42px;
    margin-bottom: 12px;

    color: #173d57;

    font-size: 29px;
    line-height: 1.25;
}

.service-info-summary {
    margin-bottom: 24px;

    color: #667f8e;

    font-size: 14px;
    line-height: 1.75;
}

.service-info-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);

    gap: 14px;

    margin-bottom: 20px;
}

.service-info-block {
    padding: 20px;

    background: #f6fafc;

    border: 1px solid #e3edf3;
    border-radius: 16px;
}

.service-info-block span {
    display: block;

    margin-bottom: 9px;

    color: #1783c2;

    font-size: 11px;
    font-weight: 800;
}

.service-info-block p {
    color: #627987;

    font-size: 13px;
    line-height: 1.7;
}

.service-info-note {
    margin-bottom: 22px;
    padding: 15px 17px;

    background: #fff8e8;
    color: #725e2f;

    border: 1px solid #f0dfb0;
    border-radius: 12px;

    font-size: 12px;
    line-height: 1.65;
}

.service-info-actions {
    display: flex;
    justify-content: flex-end;

    gap: 12px;
}

.service-info-secondary,
.service-info-primary {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    min-width: 120px;

    padding: 12px 16px;

    border-radius: 10px;

    font-family: inherit;
    font-size: 13px;
    font-weight: 800;

