    transition: 0.22s;
}

.service-info-secondary {
    background: #edf4f7;
    color: #526b78;

    border: 1px solid #d8e5eb;

    cursor: pointer;
}

.service-info-primary {
    background: #1783c2;
    color: white;

    border: 1px solid #1783c2;
}

.service-info-secondary:hover,
.service-info-primary:hover {
    transform: translateY(-2px);
}


