/* =========================================================
   V30 - REFERANS GÖRSELİ BOZMADAN HERO UYGULAMASI
   Görsel gerçek dosya oranıyla gösterilir: kırpma / esnetme yok.
   ========================================================= */

.hero {
    min-height: 0;
    padding: 0;
    display: block;
    position: relative;
    overflow: hidden;
    background: #0a0a0a;
}

.hero-reference-image {
    display: block;
    width: 100%;
    height: auto;
    max-width: none;
    object-fit: contain;
    object-position: center top;
    user-select: none;
    -webkit-user-drag: none;
}

.hero-container {
    display: none;
}

/* Referans görsel kendi menüsünü içeriyor. İlk ekranda mevcut gerçek
   header gizli tutulur; kullanıcı aşağı kaydırınca site menüsü açılır. */
#siteHeader {
    transform: translateY(-110%);
    transition: transform .28s ease, height .3s, box-shadow .3s, background .3s;
}

#siteHeader.scrolled {
    transform: translateY(0);
    background: rgba(255, 255, 255, 0.96);
}

body.dark-mode #siteHeader.scrolled {
    background: rgba(11, 24, 32, 0.96);
}

/* Küçük ekranlarda da görselin tamamı korunur; kesinlikle crop yapılmaz. */
@media (max-width: 900px) {
    .hero-reference-image {
        width: 100%;
        height: auto;
    }
}


/* =========================================
   V31 - SITE ACILISINDA REFERANS HERO
   ========================================= */

.hero.hero-v31 {
    width: 100%;
    min-height: 100vh;
    height: 100vh;
    padding: 0;
    margin: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    background: #111;
}

.hero-v31-image {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center center;
}

@media (max-width: 900px) {
    .hero.hero-v31 {
        height: auto;
        min-height: 0;
        padding: 0;
    }

    .hero-v31-image {
        width: 100%;
        height: auto;
        object-fit: contain;
    }
}


/* =========================================
   V32 - HERO ÜZERİNDE AKTİF "TEDAVİ" MENÜSÜ
   Şimdilik yalnızca 1 üst menü değiştirildi.
   ========================================= */

.hero.hero-v31 {
    position: relative;
}

/* Referans görseldeki Hakkımda konumunun üzerine gelir */
.hero-treatment-menu {
    position: absolute;
    z-index: 50;
    top: 7.0%;
    left: 13.1%;
    font-family: Arial, Helvetica, sans-serif;
}

.hero-treatment-button {
    appearance: none;
    border: 0;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 9px;

    padding: 7px 12px;
    border-radius: 8px;

    background: rgba(28, 36, 40, 0.34);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);

    color: #fff;
    font-size: clamp(12px, 0.88vw, 17px);
    line-height: 1;
    font-weight: 700;

    text-shadow: 0 1px 4px rgba(0, 0, 0, 0.55);
    transition:
        background-color .2s ease,
        transform .2s ease;
}

.hero-treatment-button:hover,
.hero-treatment-menu.open .hero-treatment-button {
    background: rgba(17, 131, 194, 0.82);
}

.hero-treatment-button:active {
    transform: translateY(1px);
}

.hero-treatment-arrow {
    display: inline-block;
    font-size: 14px;
    transition: transform .2s ease;
}

.hero-treatment-menu.open .hero-treatment-arrow {
    transform: rotate(180deg);
}

.hero-treatment-dropdown {
    position: absolute;
    top: calc(100% + 10px);
    left: 0;

    width: 210px;
    padding: 8px;

    visibility: hidden;
    opacity: 0;
    transform: translateY(-6px);
    pointer-events: none;

    background: rgba(10, 23, 31, 0.94);
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 12px;
    box-shadow: 0 18px 45px rgba(0, 0, 0, 0.28);

    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);

    transition:
        opacity .2s ease,
        transform .2s ease,
        visibility .2s ease;
}

.hero-treatment-menu.open .hero-treatment-dropdown {
    visibility: visible;
    opacity: 1;
    transform: translateY(0);
    pointer-events: auto;
}

.hero-treatment-dropdown a {
    display: block;
    padding: 11px 12px;
    border-radius: 8px;

    color: #fff;
    text-decoration: none;
    font-size: 14px;
    font-weight: 600;

    transition:
        background-color .18s ease,
        padding-left .18s ease;
}

.hero-treatment-dropdown a:hover,
.hero-treatment-dropdown a:focus-visible {
    background: rgba(23, 131, 194, 0.85);
    padding-left: 16px;
    outline: none;
}

/* Telefonda görsel küçüldüğü için menüyü uygun konuma getir */
@media (max-width: 900px) {
    .hero-treatment-menu {
        top: 6%;
        left: 12%;
    }

    .hero-treatment-button {
        font-size: 11px;
        padding: 5px 8px;
    }

    .hero-treatment-dropdown {
        width: 175px;
    }

    .hero-treatment-dropdown a {
        font-size: 12px;
        padding: 9px 10px;
    }
}


/* =========================================
   V33 - HERO "GENEL SAĞLIK" DROPDOWN
   Tedavi menüsünün hemen yanında.
   ========================================= */

.hero-health-menu {
    position: absolute;
    z-index: 50;
    top: 7.0%;
    left: 20.2%;
    font-family: Arial, Helvetica, sans-serif;
}

.hero-health-button {
    appearance: none;
    border: 0;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
