    position: absolute;
    top: 22px;
    left: 50%;
    transform: translateX(-50%);
    z-index: 12000;

    display: flex;
    align-items: center;
    gap: 14px;

    padding: 8px 10px;
    border-radius: 14px;

    background: transparent;

    transition:
        top .25s ease,
        background-color .25s ease,
        box-shadow .25s ease,
        padding .25s ease,
        border-radius .25s ease;
}

.treatment-page-nav-item {
    position: relative;
}

.treatment-page-nav-button {
    appearance: none;
    border: 1px solid rgba(255,255,255,.20);
    cursor: pointer;

    min-height: 42px;
    padding: 0 18px;

    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;

    border-radius: 10px;

    background: rgba(38, 47, 53, .82);
    color: #fff;

    font-size: 15px;
    font-weight: 700;
    white-space: nowrap;

    box-shadow: 0 5px 16px rgba(0,0,0,.14);

    transition:
        background-color .2s ease,
        transform .2s ease,
        box-shadow .2s ease;
}

.treatment-page-nav-button:hover,
.treatment-page-nav-item.open .treatment-page-nav-button {
    background: #1783c2;
}

.treatment-page-nav-button:active {
    transform: translateY(1px);
}

.treatment-page-nav-button > span {
    transition: transform .2s ease;
}

.treatment-page-nav-item.open .treatment-page-nav-button > span {
    transform: rotate(180deg);
}

.treatment-page-nav-dropdown {
    position: absolute;
    top: calc(100% + 9px);
    left: 0;

    width: 210px;
    padding: 8px;

    visibility: hidden;
    opacity: 0;
    pointer-events: none;
    transform: translateY(-6px);

    background: rgba(12, 29, 39, .97);
    border: 1px solid rgba(255,255,255,.13);
    border-radius: 12px;

    box-shadow: 0 18px 45px rgba(0,0,0,.25);

    transition:
        opacity .18s ease,
        visibility .18s ease,
        transform .18s ease;
}

