.hero-about-title-v59 {
    appearance: none;
    border: 0;
    padding: 0;
    margin: 0;

    background: transparent;
    color: #ffffff;

    cursor: pointer;

    font-family: inherit;
    font-size: clamp(58px, 5.5vw, 96px);
    font-weight: 700;
    line-height: .95;
    letter-spacing: -2px;

    text-shadow:
        0 3px 14px rgba(0,0,0,.60),
        0 1px 2px rgba(0,0,0,.85);

    transition:
        transform .2s ease,
        opacity .2s ease;
}

.hero-about-title-v59:hover {
    transform: translateY(-2px);
    opacity: .94;
}

.hero-about-title-v59:focus-visible {
    outline: 2px solid rgba(255,255,255,.95);
    outline-offset: 8px;
    border-radius: 8px;
}

