    content: "";
    position: absolute;
    z-index: 175;
    left: 0;
    right: 0;
    bottom: 0;
    height: 30%;

    background:
        linear-gradient(
            to top,
            rgba(0,0,0,.62) 0%,
            rgba(0,0,0,.24) 46%,
            rgba(0,0,0,0) 100%
        );

    pointer-events: none;
}

