/* =========================================================
   V110 - TÜM ANA SEKMELER 1.5 SN MODERN GEÇİŞ
   ========================================================= */

body.site-transition-running-v110 {
    overflow: hidden !important;
}

.site-page-transition-v110 {
    position: fixed;
    inset: 0;
    z-index: 999999;

    display: grid;
    place-items: center;

    pointer-events: none;
    visibility: hidden;
    opacity: 0;
    overflow: hidden;

    background:
        radial-gradient(
            circle at 50% 43%,
            rgba(46,185,241,.18),
            transparent 25%
        ),
        linear-gradient(
            135deg,
            rgba(5,27,42,.99),
            rgba(10,55,79,.985) 52%,
            rgba(7,35,53,.99)
        );
}

.site-page-transition-v110.is-running-v110 {
    visibility: visible;
    animation:
        siteOverlayV110 1.5s
        cubic-bezier(.22,.72,.2,1)
        both;
}

.site-transition-grid-v110 {
    position: absolute;
    inset: -8%;

    opacity: .13;

    background-image:
        linear-gradient(
            rgba(133,220,255,.12) 1px,
            transparent 1px
        ),
        linear-gradient(
            90deg,
            rgba(133,220,255,.12) 1px,
            transparent 1px
        );

    background-size: 52px 52px;

    mask-image:
        radial-gradient(
            circle at center,
            #000 0%,
            rgba(0,0,0,.75) 30%,
            transparent 72%
        );

    transform:
        perspective(700px)
        rotateX(60deg)
        translateY(32%);
}

.site-transition-glow-v110 {
    position: absolute;

    width: 420px;
    height: 420px;

    border-radius: 50%;

    filter: blur(85px);
    opacity: .20;
