/* =========================================================
   V229 - DR. CEYHUN NURI PREMIUM PULSE GLOBAL GEÇİŞ
   Seçilen 5 numaralı animasyon. Toplam süre: 1.5 saniye.
   ========================================================= */

.site-page-transition-v229 {
    background: #07131d !important;
    isolation: isolate;
}

.site-page-transition-v229::before {
    display: none !important;
}

.site-transition-v229-backdrop {
    position: absolute;
    inset: 0;
    z-index: 0;
    background:
        radial-gradient(circle at 50% 48%, rgba(202, 157, 84, .10), transparent 24%),
        radial-gradient(circle at 50% 54%, rgba(33, 91, 119, .18), transparent 42%),
        linear-gradient(145deg, #061019 0%, #0a1721 52%, #07121b 100%);
}

.site-transition-v229-aura {
    position: absolute;
    z-index: 1;
    width: 360px;
    height: 360px;
    border-radius: 50%;
    opacity: 0;
    filter: blur(85px);
    pointer-events: none;
}

.site-transition-v229-aura-a {
    left: 8%;
    top: 7%;
    background: rgba(201, 156, 83, .18);
}

.site-transition-v229-aura-b {
    right: 7%;
    bottom: 2%;
    background: rgba(38, 121, 155, .18);
}

.is-running-v110 .site-transition-v229-aura-a {
    animation: sitePremiumAuraAV229 1.5s ease-in-out both;
}

.is-running-v110 .site-transition-v229-aura-b {
    animation: sitePremiumAuraBV229 1.5s ease-in-out both;
}

.site-transition-premium-v229 {
    position: relative;
    z-index: 5;
    width: min(920px, calc(100vw - 28px));
    display: grid;
    justify-items: center;
    align-content: center;
    gap: 5px;
    opacity: 0;
    transform: translateY(10px) scale(.97);
}

.is-running-v110 .site-transition-premium-v229 {
    animation: sitePremiumStageV229 1.5s cubic-bezier(.22,.72,.2,1) both;
}

.site-transition-logo-wrap-v229 {
    position: relative;
    width: min(900px, 92vw);
    aspect-ratio: 900 / 506;
    display: grid;
    place-items: center;
    overflow: hidden;
    border-radius: 32px;
    background: #07131d;
    box-shadow:
        0 34px 100px rgba(0,0,0,.34),
        0 0 90px rgba(191, 146, 77, .08);
}

.site-transition-logo-wrap-v229::after {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    border-radius: inherit;
    box-shadow:
        inset 0 0 0 1px rgba(216, 177, 111, .08),
        inset 0 -45px 80px rgba(0,0,0,.10);
}

.site-transition-logo-v229 {
    width: 100%;
    height: 100%;
    display: block;
    object-fit: contain;
    background: #07131d;
}

.site-transition-copy-v229 {
    position: absolute;
    left: 50%;
    bottom: 20px;
    z-index: 8;
    width: min(520px, 80vw);
    transform: translateX(-50%);
    gap: 2px;
    pointer-events: none;
    text-shadow: 0 2px 12px rgba(0,0,0,.75);
}

.site-transition-copy-v229 > span {
    color: #d3ad68 !important;
    font-size: 9px !important;
    letter-spacing: .24em !important;
}

.site-transition-copy-v229 > strong {
    color: rgba(255,255,255,.96) !important;
    font-size: clamp(18px, 2.4vw, 28px) !important;
    line-height: 1.1 !important;
    letter-spacing: -.02em !important;
}

.site-transition-copy-v229 > small {
    display: none;
}

.site-transition-v229-timeline {
    position: absolute;
    left: 50%;
    bottom: 8px;
    z-index: 9;
    width: min(210px, 36vw);
    height: 2px;
    transform: translateX(-50%);
    overflow: hidden;
    border-radius: 999px;
    background: rgba(255,255,255,.07);
}

.site-transition-v229-timeline i {
    display: block;
    width: 100%;
    height: 100%;
    transform: scaleX(0);
    transform-origin: left center;
    border-radius: inherit;
    background: linear-gradient(90deg, #8b642d, #e3bd78, #fff0c7);
    box-shadow: 0 0 12px rgba(219, 178, 107, .44);
}

.is-running-v110 .site-transition-v229-timeline i {
    animation: sitePremiumTimelineV229 1.42s .04s linear forwards;
}

@keyframes sitePremiumStageV229 {
    0% {
        opacity: 0;
        transform: translateY(10px) scale(.97);
    }
    10% {
        opacity: 1;
    }
    24% {
        transform: translateY(0) scale(1);
    }
    82% {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
    100% {
        opacity: 0;
        transform: translateY(-5px) scale(1.012);
    }
}

@keyframes sitePremiumAuraAV229 {
    0% { opacity: 0; transform: scale(.72); }
    30% { opacity: .8; transform: scale(1); }
    78% { opacity: .50; }
    100% { opacity: 0; transform: scale(1.18); }
}

@keyframes sitePremiumAuraBV229 {
    0% { opacity: 0; transform: scale(.78); }
    34% { opacity: .65; transform: scale(1); }
    80% { opacity: .42; }
    100% { opacity: 0; transform: scale(1.16); }
}

@keyframes sitePremiumTimelineV229 {
    from { transform: scaleX(0); }
    to { transform: scaleX(1); }
}

@media (max-width: 680px) {
