/* =========================================================
   V250 - HASTALIKLAR ARASI MODERN HIZLI GEÇİŞ
   AS, RA ve diğer tedavi alanı hastalıklarında ortak kullanılır.
   ========================================================= */
.disease-switcher-v250 {
    position: relative;
    z-index: 80;
    width: min(1510px, calc(100% - 44px));
    margin-left: auto;
    margin-right: auto;
    padding: 18px;
    border: 1px solid rgba(36, 132, 190, .14);
    border-radius: 28px;
    background:
        radial-gradient(circle at 92% 0%, rgba(72, 189, 233, .14), transparent 27%),
        linear-gradient(135deg, rgba(255,255,255,.97), rgba(241,249,253,.98));
    box-shadow: 0 18px 46px rgba(18, 73, 108, .10), inset 0 1px 0 rgba(255,255,255,.96);
    overflow: hidden;
}

.disease-switcher-v250::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 5px;
    background: linear-gradient(180deg, #20a8e5, #1689cb 52%, #29c0a4);
}

.disease-switcher-head-v250 {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 18px;
    margin-bottom: 14px;
    padding: 0 4px 0 8px;
}

.disease-switcher-head-v250 > div {
    display: flex;
    align-items: baseline;
    gap: 12px;
    flex-wrap: wrap;
}

.disease-switcher-head-v250 span {
    color: #168bc4;
    font-size: 10px;
    font-weight: 950;
    letter-spacing: .16em;
}

.disease-switcher-head-v250 strong {
    color: #123f5e;
    font-size: 18px;
    font-weight: 900;
    letter-spacing: -.015em;
}

.disease-switcher-head-v250 small {
    color: #7892a3;
    font-size: 12px;
    font-weight: 700;
    text-align: right;
}

.disease-switch-grid-v250 {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 10px;
}

.disease-switch-card-v250 {
    appearance: none;
    width: 100%;
    min-height: 62px;
    padding: 8px 10px 8px 9px;
    border: 1px solid rgba(39, 127, 181, .13);
    border-radius: 18px;
    background: rgba(255,255,255,.90);
    color: #174663;
    box-shadow: 0 8px 18px rgba(25, 77, 109, .055);
    display: grid;
    grid-template-columns: 36px minmax(0, 1fr) 32px;
    align-items: center;
    gap: 10px;
    text-align: left;
    cursor: pointer;
    transition: transform .20s ease, border-color .20s ease, box-shadow .20s ease, background .20s ease, color .20s ease;
}

.disease-switch-card-v250:hover,
.disease-switch-card-v250:focus-visible {
    outline: none;
    transform: translateY(-2px);
    border-color: rgba(23, 145, 205, .34);
    background: #fff;
    box-shadow: 0 14px 28px rgba(25, 89, 128, .11);
}

.disease-switch-code-v250,
.disease-switch-arrow-v250 {
    display: grid;
    place-items: center;
    width: 32px;
    height: 32px;
    border-radius: 11px;
    background: #edf7fb;
    color: #1687c5;
    font-size: 10px;
    font-weight: 950;
}

.disease-switch-card-v250 strong {
    min-width: 0;
    font-size: 14px;
    font-weight: 900;
    line-height: 1.18;
}

.disease-switch-arrow-v250 {
    justify-self: end;
    border-radius: 999px;
    font-size: 13px;
    transition: transform .20s ease;
}

.disease-switch-card-v250:hover .disease-switch-arrow-v250,
.disease-switch-card-v250:focus-visible .disease-switch-arrow-v250 {
    transform: translate(2px,-2px);
}

.disease-switch-card-v250.is-active {
    border-color: rgba(37, 160, 220, .50);
    background: linear-gradient(135deg,#168dcc 0%,#1678b8 58%,#126b9d 100%);
    color: #fff;
    box-shadow: 0 13px 28px rgba(19, 124, 183, .22), inset 0 1px 0 rgba(255,255,255,.22);
    cursor: default;
