/* =========================================================
   V272 - OSTEOPATİ HIZLI KARTLAR -> ÖZEL SAYFA GEÇİŞ ANİMASYONU
   Kart tıklanınca premium geçiş ekranı ve hedef sekme animasyonu.
   ========================================================= */

.osteo-hero-launch-card-v261 {
    overflow: hidden;
    transform-origin: center;
}

.osteo-hero-launch-card-v261::before {
    content: "";
    position: absolute;
    inset: -45%;
    z-index: 0;
    background:
        linear-gradient(
            115deg,
            transparent 32%,
            rgba(116, 221, 255, .04) 42%,
            rgba(116, 221, 255, .22) 50%,
            rgba(116, 221, 255, .04) 58%,
            transparent 68%
        );
    transform: translateX(-120%) rotate(8deg);
    transition: transform .55s ease;
    pointer-events: none;
}

.osteo-hero-launch-card-v261:hover::before,
.osteo-hero-launch-card-v261:focus-visible::before {
    transform: translateX(120%) rotate(8deg);
}

.osteo-hero-launch-card-v261 > * {
    position: relative;
    z-index: 1;
}

.osteo-hero-launch-card-v261.is-launching-v272 {
    pointer-events: none;
    animation: osteoCardLaunchV272 .55s cubic-bezier(.2,.85,.25,1) forwards;
}

@keyframes osteoCardLaunchV272 {
    0% {
        transform: translateY(0) scale(1);
        box-shadow: 0 10px 24px rgba(4, 37, 57, .08);
    }
    42% {
        transform: translateY(-4px) scale(1.025);
        box-shadow: 0 18px 38px rgba(22, 156, 214, .23);
    }
    100% {
        transform: translateY(2px) scale(.97);
        opacity: .70;
    }
}

/* Tam ekran geçiş katmanı */
.osteo-route-transition-v272 {
    position: fixed;
    inset: 0;
    z-index: 999998;
    display: grid;
    place-items: center;
    padding: 24px;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    overflow: hidden;
    background:
        radial-gradient(circle at 50% 45%, rgba(34, 169, 226, .18), transparent 28%),
