/* =========================================================
   V321 - PERSONEL FOTOĞRAFLARI / DAHA CANLI MİKRO ANİMASYON
   ========================================================= */
#aboutPanelTeamV316 .team-card-v316{
    perspective:1100px;
    transform-style:preserve-3d;
    --tiltX:0deg;
    --tiltY:0deg;
    --photoX:0px;
    --photoY:0px;
}

#aboutPanelTeamV316 .team-card-v316.is-revealed-v321{
    animation:teamCardRevealV321 .64s cubic-bezier(.22,.8,.24,1) both;
    animation-delay:var(--revealDelay,0ms);
}

@keyframes teamCardRevealV321{
    0%{opacity:0;transform:translateY(24px) scale(.975)}
    100%{opacity:1;transform:translateY(0) scale(1)}
}

#aboutPanelTeamV316 .team-card-media-v316{
    transform-style:preserve-3d;
    transition:transform .38s cubic-bezier(.2,.75,.2,1), box-shadow .38s ease, border-color .3s ease;
    will-change:transform;
}

#aboutPanelTeamV316 .team-card-media-v316.has-photo-v317{
    box-shadow:
        inset 0 1px 0 rgba(255,255,255,.95),
        0 14px 28px rgba(10,72,109,.10)!important;
}

#aboutPanelTeamV316 .team-card-media-v316.has-photo-v317::before{
    content:"";
    position:absolute;
    inset:-35% auto -35% -38%;
    width:34%;
    z-index:3;
    pointer-events:none;
    opacity:0;
    transform:skewX(-18deg) translateX(-180%);
    background:linear-gradient(90deg,transparent,rgba(255,255,255,.58),transparent);
}

#aboutPanelTeamV316 .team-card-media-v316.has-photo-v317 img{
    transform:translate3d(var(--photoX),var(--photoY),0) scale(1.025);
    transition:transform .42s cubic-bezier(.2,.75,.2,1), filter .42s ease;
    will-change:transform;
    animation:teamPhotoBreathV321 7.5s ease-in-out infinite alternate;
}

@keyframes teamPhotoBreathV321{
    0%{transform:translate3d(var(--photoX),calc(var(--photoY) + 1px),0) scale(1.025)}
    100%{transform:translate3d(var(--photoX),calc(var(--photoY) - 4px),0) scale(1.052)}
}

#aboutPanelTeamV316 .team-card-v316:hover .team-card-media-v316.has-photo-v317,
#aboutPanelTeamV316 .team-card-v316.is-photo-hover-v321 .team-card-media-v316.has-photo-v317{
    transform:rotateX(var(--tiltX)) rotateY(var(--tiltY)) translateY(-4px) scale(1.012);
    border-color:rgba(58,174,234,.52)!important;
    box-shadow:
        inset 0 1px 0 rgba(255,255,255,.96),
        0 20px 38px rgba(9,76,116,.18)!important;
}

#aboutPanelTeamV316 .team-card-v316:hover .team-card-media-v316.has-photo-v317::before,
#aboutPanelTeamV316 .team-card-v316.is-photo-hover-v321 .team-card-media-v316.has-photo-v317::before{
    opacity:1;
    animation:teamPhotoShineV321 1.05s ease forwards;
}

@keyframes teamPhotoShineV321{
    from{transform:skewX(-18deg) translateX(-180%)}
    to{transform:skewX(-18deg) translateX(520%)}
}

#aboutPanelTeamV316 .team-card-v316:hover .team-card-media-v316.has-photo-v317 img,
#aboutPanelTeamV316 .team-card-v316.is-active .team-card-media-v316.has-photo-v317 img{
    filter:saturate(1.08) contrast(1.025) brightness(1.015);
}

#aboutPanelTeamV316 .team-card-v316.photo-pop-v321 .team-card-media-v316.has-photo-v317{
    animation:teamPhotoPopV321 .58s cubic-bezier(.2,.85,.2,1);
}

@keyframes teamPhotoPopV321{
    0%{transform:scale(1)}
    38%{transform:scale(1.025) rotateZ(.45deg)}
    100%{transform:scale(1)}
}

#aboutPanelTeamV316 .team-card-v316.photo-pop-v321 .team-card-badge-v316{
    animation:teamBadgePulseV321 .62s ease;
}

@keyframes teamBadgePulseV321{
    0%,100%{box-shadow:0 10px 24px rgba(6,40,63,.24)}
    50%{box-shadow:0 0 0 8px rgba(47,176,241,.12),0 14px 32px rgba(6,40,63,.32)}
}

#aboutPanelTeamV316 .team-card-media-v316.has-photo-v317::after{
    transition:opacity .35s ease, height .35s ease;
}
#aboutPanelTeamV316 .team-card-v316:hover .team-card-media-v316.has-photo-v317::after{
    opacity:.72;
    height:40%;
}

@media (prefers-reduced-motion: reduce){
    #aboutPanelTeamV316 .team-card-v316,
    #aboutPanelTeamV316 .team-card-media-v316,
    #aboutPanelTeamV316 .team-card-media-v316 img,
    #aboutPanelTeamV316 .team-card-badge-v316{
        animation:none!important;
        transition:none!important;
        transform:none!important;
    }
    #aboutPanelTeamV316 .team-card-media-v316::before{display:none!important}
}


