/* =========================================================
   V324 - YAZI HİYERARŞİSİ
   Başlıklar / menüler / butonlar: Manrope
   Açıklamalar / paragraflar / uzun metinler: Inter
   ========================================================= */
:root{
    --font-heading-v324: "Manrope", "Segoe UI", Arial, sans-serif;
    --font-body-v324: "Inter", "Segoe UI", Arial, sans-serif;
}

/* Gövde ve okunabilir uzun metinler */
html,
body,
p,
li,
label,
input,
textarea,
select,
option,
td,
th,
figcaption,
small,
blockquote,
address,
summary,
details,
article,
section{
    font-family:var(--font-body-v324)!important;
}

body{
    font-family:var(--font-body-v324)!important;
    font-weight:400;
    font-feature-settings:"kern" 1,"liga" 1;
    text-rendering:optimizeLegibility;
}

/* Ana başlıklar, bölüm başlıkları ve kart başlıkları */
h1,
h2,
h3,
h4,
h5,
h6,
[class*="title"],
[class*="heading"],
[class*="headline"],
[class*="kicker"],
[class*="eyebrow"],
[class*="section-name"],
[class*="card-name"],
[class*="brand-copy"] strong,
[class*="brand"] strong,
[class*="card"] > strong,
[class*="card"] h2,
[class*="card"] h3,
[class*="card"] h4,
[class*="panel"] h2,
[class*="panel"] h3{
    font-family:var(--font-heading-v324)!important;
}

h1{
    font-weight:800!important;
    letter-spacing:-.045em;
}
h2{
    font-weight:800!important;
    letter-spacing:-.035em;
}
h3,
h4,
h5,
h6{
    font-weight:700!important;
    letter-spacing:-.02em;
}

/* Butonlar, sekmeler ve üst menüler */
button,
[role="button"],
[class*="button"],
[class*="btn"],
[class*="tab"],
[class*="nav"] a,
nav a,
nav button,
.menu-item,
[class*="menu"] a,
[class*="menu"] button{
    font-family:var(--font-heading-v324)!important;
    font-weight:700;
}

/* Kart başlığındaki güçlü metinler Manrope; açıklama içindeki vurgu Inter kalsın */
[class*="card"] > strong,
[class*="card"] .card-title,
[class*="card"] [class*="title"]{
    font-family:var(--font-heading-v324)!important;
    font-weight:700!important;
}

/* Açıklama ve yardımcı metinlerde Inter netliği */
[class*="desc"],
[class*="description"],
[class*="copy"],
[class*="text"],
[class*="note"],
[class*="excerpt"],
[class*="summary"] p,
[class*="card"] p,
[class*="panel"] p{
    font-family:var(--font-body-v324)!important;
}

/* Logo/marka ve büyük hero başlıklarında premium başlık karakteri */
.logo-title,
.site-title,
.hero-title,
[class*="hero"] h1,
[class*="hero"] h2,
[class*="hero"] h3{
    font-family:var(--font-heading-v324)!important;
    font-weight:800!important;
}

/* Form alanlarında uzun metin okuma rahatlığı */
input,
textarea,
select{
    font-family:var(--font-body-v324)!important;
    font-weight:500;
}

/* Mobilde başlıkların sıkışmasını azalt */
@media(max-width:760px){
    h1,h2,[class*="hero"] h1,[class*="hero"] h2{
        letter-spacing:-.03em!important;
    }
}


