/* =========================================================
   V334 - DETAY YAZILARININ ALTINDA DİĞER SERUMLAR
   ========================================================= */

.other-serums-v334 {
    grid-column: 1 / -1;
    width: 100%;
    margin: 4px 0 0;
    padding: 17px 18px 18px;
    border: 1px solid rgba(28, 135, 193, .13);
    border-radius: 18px;
    background:
        radial-gradient(circle at 94% 8%, rgba(64, 185, 236, .10), transparent 28%),
        linear-gradient(180deg, #f8fcff 0%, #edf7fc 100%);
}

.other-serums-head-v334 {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 18px;
    margin-bottom: 12px;
}

.other-serums-kicker-v334 {
    display: block;
    margin-bottom: 4px;
    color: #1689c4;
    font-family: "Manrope", Arial, sans-serif;
    font-size: 9px;
    font-weight: 800;
    letter-spacing: .16em;
    text-transform: uppercase;
}

.other-serums-head-v334 h3 {
    margin: 0;
    color: #123f5b;
    font-family: "Manrope", Arial, sans-serif;
    font-size: 20px;
    line-height: 1.15;
    font-weight: 800;
}

.other-serums-head-v334 p {
    max-width: 500px;
    margin: 0;
    color: #6a8495;
    font-family: "Inter", Arial, sans-serif;
    font-size: 12px;
    line-height: 1.45;
    text-align: right;
}

.other-serums-grid-v334 {
    display: grid;
    grid-template-columns: repeat(6, minmax(0, 1fr));
    gap: 8px;
}

.other-serum-button-v334 {
    appearance: none;
    width: 100%;
    min-height: 62px;
    padding: 10px 11px;
    display: flex;
    align-items: center;
    gap: 9px;
    border: 1px solid rgba(22, 137, 196, .13);
    border-radius: 13px;
    background: rgba(255,255,255,.92);
    color: #163f59;
    text-align: left;
    cursor: pointer;
    box-shadow: 0 6px 16px rgba(13, 71, 104, .035);
    transition: transform .18s ease, border-color .18s ease, box-shadow .18s ease, background .18s ease;
}

.other-serum-button-v334:hover,
.other-serum-button-v334:focus-visible {
    transform: translateY(-2px);
    border-color: rgba(21, 151, 213, .38);
    background: #fff;
    box-shadow: 0 10px 22px rgba(13, 81, 121, .09);
    outline: none;
}

.other-serum-index-v334 {
    flex: 0 0 auto;
    width: 31px;
    height: 31px;
    display: grid;
    place-items: center;
    border-radius: 10px;
    background: #e7f5fc;
    color: #0f8dca;
    font-family: "Manrope", Arial, sans-serif;
    font-size: 10px;
    font-weight: 800;
}

.other-serum-copy-v334 {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.other-serum-copy-v334 strong {
    overflow: hidden;
    color: #153c55;
    font-family: "Manrope", Arial, sans-serif;
    font-size: 12px;
    font-weight: 800;
    line-height: 1.15;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.other-serum-copy-v334 span {
    color: #7890a0;
    font-family: "Inter", Arial, sans-serif;
    font-size: 9px;
    line-height: 1.2;
}

@media (max-width: 1180px) {
    .other-serums-grid-v334 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

@media (max-width: 700px) {
    .other-serums-v334 {
        padding: 14px;
        border-radius: 16px;
    }

    .other-serums-head-v334 {
        align-items: flex-start;
        flex-direction: column;
        gap: 5px;
    }

    .other-serums-head-v334 p {
        text-align: left;
    }

    .other-serums-grid-v334 {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .other-serum-button-v334 {
        min-height: 58px;
    }
}


